```javascript
function parseArrayBuffer(arrayBuffer) {
    const view = new DataView(arrayBuffer);

    // Check the magic signature
    const magicSignature = new TextDecoder('utf-8').decode(new Uint8Array(arrayBuffer, 0, 4));
    if (magicSignature !== 'MYSIG') {
        return { error: 'Invalid magic signature' };
    }

    // Read the file version
    const fileVersion = view.getUint32(4, false); // Little-endian

    // Read the data size
    const dataSize = view.getUint32(8, false); // Little-endian

    // Read the data
    const dataView = new DataView(arrayBuffer, 12, dataSize);
    let parsedData = [];
    for (let i = 0; i < dataSize; i += 1) {
        const charCode = dataView.getUint8(i);
        if (charCode === 0) {
            break; // End of string
        }
        parsedData.push(String.fromCharCode(charCode));
    }

    // Return the parsed object
    return { parsed_object: parsedData.join('') };
}

