Below is an example of creating a simple `StatelessWidget`:

```dart
import 'package:flutter/material.dart';

// Define a StatelessWidget
class MyCustomWidget extends StatelessWidget {
  // Constructor
  const MyCustomWidget({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    // Return a widget tree
    return Container(
      color: Colors.blue,
      child: Center(
        child: Text('Hello, Stateless Widget!'),
      ),
    );
  }
}

void main() {
  runApp(MyApp());
}

class MyApp extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(
          title: Text('Stateless Widget Example'),
        ),
        body: MyCustomWidget(),
      ),
    );
  }
}
```

