Hashing all files in a directory and its subdirectories can be done using a script. Below are examples for both Python and Bash, which are commonly used for such tasks.

### Using Python

You can use the `os` and `hashlib` modules to recursively hash all files in a directory and its subdirectories.

```python
import os
import hashlib

def hash_file(file_path, hash_type='sha1'):
    """Hash a file using the specified hash type."""
    if hash_type == 'sha1':
        hash_obj = hashlib.sha1()
    elif hash_type == 'md5':
        hash_obj = hashlib.md5()
    else:
        raise ValueError("Unsupported hash type")

    with open(file_path, 'rb') as f:
        while chunk := f.read(8192):
            hash_obj.update(chunk)
    return hash_obj.hexdigest()

def hash_directory(directory, hash_type='sha1'):
    """Hash all files in a directory and its subdirectories."""
    hashes = {}
    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            file_hash = hash_file(file_path, hash_type)
            hashes[file_path] = file_hash
    return hashes

# Example usage
directory_path = '/path/to/directory'
hashes = hash_directory(directory_path, 'sha1')
for file_path, file_hash in hashes.items():
    print(f"{file_path}: {file_hash}")
```

